def policy(state, tools):
    a = tools.score('mlp5', 'ucb', beta=0.5)
    b = tools.score('epistasis_pairwise', 'ucb', beta=0.5)
    scores = tools.blend(a, b, weight=0.5)
    return tools.select(scores)
